<?php
require_once 'inc/db.php';require_once 'inc/auth.php';if(!in_array((int)$_SESSION['role_id'],[1,2],true)){http_response_code(403);die('Access denied.');}
$status=$db->query('SELECT status label,COUNT(*) total FROM tbl_road_reports GROUP BY status ORDER BY total DESC')->fetchAll(PDO::FETCH_ASSOC);$regions=$db->query("SELECT COALESCE(NULLIF(province,''),'Unspecified') label,COUNT(*) total,SUM(status='Resolved') resolved,ROUND(AVG(priority_score),0) average_priority FROM tbl_road_reports GROUP BY province ORDER BY total DESC")->fetchAll(PDO::FETCH_ASSOC);$types=$db->query('SELECT dt.type_name label,COUNT(*) total FROM tbl_road_reports r JOIN tbl_damage_types dt ON dt.type_id=r.damage_type_id GROUP BY dt.type_id ORDER BY total DESC')->fetchAll(PDO::FETCH_ASSOC);$maxStatus=max(array_column($status,'total')?:[1]);$maxType=max(array_column($types,'total')?:[1]);$page_title='Road Condition Analytics';$breadcrumb='Decision support';include 'inc/links.php';include 'inc/header.php';?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php';?><section role="main" class="content-body"><?php include 'inc/inner-header.php';?><div class="analytics-note"><i class="fa fa-line-chart"></i><div><strong>Maintenance decision support</strong><span>Live summaries help RTDA prioritize inspections, allocate repair resources, and monitor regional response.</span></div></div><div class="row"><div class="col-md-6"><section class="panel"><header class="panel-heading"><span class="panel-overline">Workflow health</span><h2 class="panel-title">Reports by status</h2></header><div class="panel-body chart-list"><?php foreach($status as $x):?><div class="chart-row"><div><span><?php echo e($x['label']);?></span><strong><?php echo (int)$x['total'];?></strong></div><i><b style="width:<?php echo round($x['total']/$maxStatus*100);?>%"></b></i></div><?php endforeach;?></div></section></div><div class="col-md-6"><section class="panel"><header class="panel-heading"><span class="panel-overline">Defect profile</span><h2 class="panel-title">Damage classifications</h2></header><div class="panel-body chart-list"><?php foreach($types as $x):?><div class="chart-row"><div><span><?php echo e($x['label']);?></span><strong><?php echo (int)$x['total'];?></strong></div><i><b style="width:<?php echo round($x['total']/$maxType*100);?>%"></b></i></div><?php endforeach;?></div></section></div></div><section class="panel"><header class="panel-heading"><span class="panel-overline">Resource allocation</span><h2 class="panel-title">Maintenance planning by region</h2></header><div class="panel-body table-responsive"><table class="table"><thead><tr><th>Province</th><th>Reports</th><th>Resolved</th><th>Resolution rate</th><th>Average priority</th></tr></thead><tbody><?php foreach($regions as $x):?><tr><td><strong><?php echo e($x['label']);?></strong></td><td><?php echo (int)$x['total'];?></td><td><?php echo (int)$x['resolved'];?></td><td><?php echo $x['total']?round($x['resolved']/$x['total']*100):0;?>%</td><td><span class="priority-pill"><?php echo (int)$x['average_priority'];?>/100</span></td></tr><?php endforeach;?></tbody></table></div></section></section></div><?php include 'inc/scripts.php';?>
